def clean(df):
    df['species'] = df['species'].str.strip()
    df = df[df['species'] == 'Adelie']
    df['island'] = df['island'].str.strip()
    allowed_islands = {'Biscoe', 'Dream', 'Torgersen'}
    df = df[df['island'].isin(allowed_islands)]
    df = df[df['bill_length_mm'].between(30, 60)]
    return df

def answer(df):
    grouped = df.groupby('island')['bill_length_mm'].mean()
    return {k: v for k, v in grouped.items() if v is not None}
